 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find substantial 4-connected components of non-background colors; these
    # are the solid rectangular objects obscured by scattered noise.
    candidates = {}
    for color in {v for row in grid for v in row if v != background}:
        seen = set()
        largest = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                component = []
                while q:
                    x, y = q.popleft()
                    component.append((x, y))
                    for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                            seen.add((nx, ny))
                            q.append((nx, ny))
                if len(component) > len(largest):
                    largest = component
        if len(largest) >= 4:
            candidates[color] = largest

    out = [[background for _ in range(w)] for _ in range(h)]
    for color, component in candidates.items():
        r0 = min(r for r, c in component)
        r1 = max(r for r, c in component)
        c0 = min(c for r, c in component)
        c1 = max(c for r, c in component)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
